@startuml

class Employee {
  + Name : string
  + Ssn : int
}

class CreativeEmployee extends Employee {
  + OscarWinner : boolean
}

class Director extends CreativeEmployee {
  + AssistantName : string
}

class Actor extends CreativeEmployee {
  + Education : string
}

class Technician extends Employee {
  + FieldOfActivity : string
}

class Location {
  + Name : string
}

class Film {
  + Title : string
  + ReleaseYear : int
}

class Genre {
  + Type : string
}

class Screenwriter {
  + Name : string
  + MostSuccessfulFilm : string
}

class Screenplay {
  + Title : string
  + Version : string
  + Date : date
  + NumberOfScenes : int
  + Plot : string
}

class Novel {
  + Title : string
  + Author : string
}

class Concept {
}

Film "1" -- "*" FilmSet : shot_at
FilmSet "*" -- "1" Location : located_at
FilmSet "*" -- "1" Film : used_for

Film "1" -- "1" Genre : assigned_to
Film "1" -- "1" Screenplay : based_on
Film "1" -- "1" Director : directed_by
Film "1" -- "*" Actor : features

Screenwriter "1" -- "*" Screenplay : creates
Screenplay "1" -- "1" Film : written_for
Screenplay "0..1" -- "0..1" Novel : based_on
Screenplay "0..1" -- "0..1" Concept : based_on

Actor "*" -- "1" Screenplay : reads_for

class FilmSet {}

@enduml

